import pytest

DEFAULT_MODE = "fast"
DEFAULT_LEVEL = "3"


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay settings on the defaults mode=fast and level=3.

    keys[i] is set to values[i]. Returns the resulting values: first the
    value of "mode", then of "level", then the values of any other keys in
    the order each key first appears in `keys`. If a key repeats, the last
    value given for it wins but its position is that of its first appearance.

    Raises ValueError if keys and values differ in length.
    Pure function: no I/O, environment, or other capabilities are used.
    """
    if len(keys) != len(values):
        raise ValueError("keys and values must have the same length")
    merged: dict[str, str] = {"mode": DEFAULT_MODE, "level": DEFAULT_LEVEL}
    for k, v in zip(keys, values, strict=True):
        merged[k] = v
    return list(merged.values())


def test_defaults_only() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_mode() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_override_level() -> None:
    assert settings(["level"], ["9"]) == ["fast", "9"]


def test_override_both_in_reverse_order() -> None:
    assert settings(["level", "mode"], ["1", "slow"]) == ["slow", "1"]


def test_extra_keys_in_given_order() -> None:
    assert settings(["z", "a"], ["26", "1"]) == ["fast", "3", "26", "1"]


def test_extras_interleaved_with_known_keys() -> None:
    assert settings(["x", "mode", "y"], ["1", "slow", "2"]) == [
        "slow",
        "3",
        "1",
        "2",
    ]


def test_duplicate_keys_last_value_first_position() -> None:
    assert settings(["a", "b", "a"], ["1", "2", "3"]) == ["fast", "3", "3", "2"]


def test_duplicate_known_key() -> None:
    assert settings(["mode", "mode"], ["slow", "turbo"]) == ["turbo", "3"]


def test_empty_string_value_is_kept() -> None:
    assert settings(["mode", "a"], ["", ""]) == ["", "3", ""]


def test_mismatched_lengths_raise() -> None:
    with pytest.raises(ValueError):
        settings(["a", "b"], ["1"])
    with pytest.raises(ValueError):
        settings([], ["1"])


def test_inputs_not_mutated() -> None:
    keys = ["mode", "a"]
    values = ["slow", "1"]
    settings(keys, values)
    assert keys == ["mode", "a"]
    assert values == ["slow", "1"]
